import{_ as s,C as n,o as a,c as r,a2 as e,E as i}from"./chunks/framework.TaNiW7i8.js";const f=JSON.parse('{"title":"Connect your agents","description":"","frontmatter":{"title":"Connect your agents"},"headers":[],"relativePath":"en/guide/agents.md","filePath":"en/guide/agents.md"}'),l={name:"en/guide/agents.md"};function d(h,t,c,g,u,p){const o=n("Capture");return a(),r("div",null,[t[0]||(t[0]=e('<h1 id="connect-your-agents" tabindex="-1">Connect your agents <a class="header-anchor" href="#connect-your-agents" aria-label="Permalink to &quot;Connect your agents&quot;">​</a></h1><p>For an AI assistant to read and add to your memory, it must know Kessho&#39;s MCP server, <code>kessho-mcp</code>. Kessho declares it itself in the assistants installed on your machine, in one click. This page shows how, and exactly what Kessho writes into them.</p><h2 id="supported-assistants" tabindex="-1">Supported assistants <a class="header-anchor" href="#supported-assistants" aria-label="Permalink to &quot;Supported assistants&quot;">​</a></h2><p>Kessho declares its server in these ten clients:</p><table tabindex="0"><thead><tr><th>Client</th><th>Configuration file modified</th></tr></thead><tbody><tr><td>Claude Code</td><td><code>~/.claude.json</code></td></tr><tr><td>Claude Desktop</td><td><code>~/Library/Application Support/Claude/claude_desktop_config.json</code> (macOS)</td></tr><tr><td>Codex</td><td><code>~/.codex/config.toml</code></td></tr><tr><td>Gemini CLI</td><td><code>~/.gemini/settings.json</code></td></tr><tr><td>Mistral Vibe</td><td><code>~/.vibe/config.toml</code></td></tr><tr><td>GitHub Copilot CLI</td><td><code>~/.copilot/mcp-config.json</code></td></tr><tr><td>Antigravity</td><td><code>~/.gemini/config/mcp_config.json</code></td></tr><tr><td>Antigravity (application)</td><td><code>~/.gemini/antigravity/mcp_config.json</code></td></tr><tr><td>Antigravity (CLI)</td><td><code>~/.gemini/antigravity-cli/mcp_config.json</code></td></tr><tr><td>opencode</td><td><code>~/.config/opencode/opencode.json</code></td></tr></tbody></table><p>A client that is not installed shows as &quot;Not detected&quot;: Kessho writes no declaration into it. However, <strong>Auto-inject</strong> also tidies up old Antigravity and Gemini leftovers (the old <code>memory-kit</code> extension and its enablement entries in <code>~/.gemini/</code>), with a backup before each change.</p><h2 id="what-kessho-writes" tabindex="-1">What Kessho writes <a class="header-anchor" href="#what-kessho-writes" aria-label="Permalink to &quot;What Kessho writes&quot;">​</a></h2><ul><li>An entry named <code>kessho</code>, pointing to the <code>kessho-mcp</code> program, looked for next to the application and then in the <code>PATH</code>. It carries <strong>no argument</strong>: the server finds your memory on its own.</li><li><strong>A backup first</strong>: before changing a file, Kessho keeps a copy next to it, named <code>&lt;file&gt;.bak.&lt;timestamp&gt;</code>. If the backup fails, nothing is written.</li><li><strong>No permission granted</strong>: Kessho adds nothing to your assistants&#39; allow lists.</li><li><strong>No program launched</strong> to declare the server: Kessho writes to the file, and that is all.</li><li>Declarations inherited from an old server are removed from the file along the way, and the screen says so (&quot;Legacy declarations removed&quot;).</li></ul><h2 id="declare-kessho-to-your-assistants" tabindex="-1">Declare Kessho to your assistants <a class="header-anchor" href="#declare-kessho-to-your-assistants" aria-label="Permalink to &quot;Declare Kessho to your assistants&quot;">​</a></h2>',9)),i(o,{name:"connecteurs",alt:"The MCP agent connectors screen: the list of clients with their state and configuration file, and the “Probe the server”, “Auto-inject” and “Uninstall” buttons."}),t[1]||(t[1]=e('<ol><li>Open <strong>Settings</strong>, then the <strong>MCP connectors</strong> section.</li><li>The table lists each client with its <strong>State</strong> and its <strong>Configuration</strong> file. Above it, counters sum up: &quot;8 deployed&quot;, &quot;0 to configure&quot;, &quot;0 residual&quot;.</li><li>Click <strong>Auto-inject</strong>. It acts on all detected clients at once: there is no client-by-client deployment.</li><li>Every detected client moves to <strong>Deployed</strong>. The <strong>Deployment</strong> panel on the right gives the two counts: <strong>Clients detected</strong> and <strong>Declarations written</strong>.</li></ol><p>During the <a href="/Kessho/en/guide/first-run.html">first launch</a> wizard, the <strong>Connectors</strong> step does the same with the <strong>Declare Kessho to my assistants</strong> button.</p><p>If macOS shows &quot;macOS is running a temporary copy&quot;, move Kessho into the Applications folder using Finder (drag and drop, not copy), then relaunch it. Otherwise Kessho would write into your tools a path that disappears when the app closes.</p><h2 id="reading-a-client-s-state" tabindex="-1">Reading a client&#39;s state <a class="header-anchor" href="#reading-a-client-s-state" aria-label="Permalink to &quot;Reading a client&#39;s state&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Label</th><th>What it means</th></tr></thead><tbody><tr><td><strong>Deployed</strong></td><td>The client is detected and Kessho is declared in its configuration.</td></tr><tr><td><strong>To configure</strong></td><td>The client is installed, but Kessho is not declared in it yet. Click <strong>Auto-inject</strong>.</td></tr><tr><td><strong>Not detected</strong></td><td>The client is not installed on this machine. This is not a failure.</td></tr><tr><td><strong>Residual</strong></td><td>The client has left this machine; its declaration is still written.</td></tr><tr><td><strong>Deployment failed</strong></td><td>The write failed. Hover over the state: the reason appears.</td></tr></tbody></table><p>Without opening the settings, you also see the essentials elsewhere: the status bar at the bottom shows <strong>AGENTS 6/8</strong> (the number of detected clients that carry Kessho, out of the number of detected clients), and the home screen shows the <strong>Machine state</strong> card with <strong>Open settings</strong>.</p><h2 id="check-that-the-server-answers" tabindex="-1">Check that the server answers <a class="header-anchor" href="#check-that-the-server-answers" aria-label="Permalink to &quot;Check that the server answers&quot;">​</a></h2><p>Click <strong>Probe the server</strong>. Kessho starts its own server and measures its answer:</p><ul><li>&quot;Server reachable · 42 ms&quot;: all is well;</li><li>&quot;Server silent&quot;: it started but did not answer in time;</li><li>&quot;Binary not found&quot;: the declared program does not exist or could not be started;</li><li>&quot;Probe failed&quot;: the check itself failed.</li></ul><p>The probe tests <strong>Kessho&#39;s server</strong>, not your assistants: it says nothing about whether a client uses it.</p><h2 id="try-a-tool-safely" tabindex="-1">Try a tool safely <a class="header-anchor" href="#try-a-tool-safely" aria-label="Permalink to &quot;Try a tool safely&quot;">​</a></h2><p>At the bottom left, the <strong>Test bench</strong> (labelled &quot;simulation&quot;) lets you see what a tool call looks like.</p><ol><li>Pick a tool in the list. Tools that write are marked &quot;writes&quot;; tools not yet available are marked &quot;not implemented&quot; (and cannot be selected).</li><li>Adjust the <strong>JSON payload</strong> if needed.</li><li>Click <strong>Run</strong>.</li></ol><p>The bench <strong>runs nothing</strong>: it checks that your JSON is valid and echoes it back. No memory data is read or written. The full list of tools is in the <a href="/Kessho/en/reference/mcp/">MCP reference</a>.</p><h2 id="removing-kessho-from-a-client" tabindex="-1">Removing Kessho from a client <a class="header-anchor" href="#removing-kessho-from-a-client" aria-label="Permalink to &quot;Removing Kessho from a client&quot;">​</a></h2><ol><li>In the table, click the client&#39;s row (a second click deselects it).</li><li>Click <strong>Uninstall</strong>. The button is only active for a <strong>Deployed</strong> or <strong>Residual</strong> client.</li><li>Read the confirmation: &quot;Removes the Kessho entry from … No permission is changed.&quot;</li><li>Click <strong>Confirm removal</strong>, or <strong>Cancel</strong>.</li></ol><p>Only Kessho&#39;s entry is removed, and a backup is taken if the file changes. If the removal fails, the screen names the client concerned.</p><h2 id="the-old-server" tabindex="-1">The old server <a class="header-anchor" href="#the-old-server" aria-label="Permalink to &quot;The old server&quot;">​</a></h2><p>If an old Kessho server is still on your disk, the <strong>Deployment</strong> panel flags it (&quot;Previous server still installed&quot;): no client launches it any more. The <strong>Remove this binary</strong> button deletes it after confirmation, and a copy is kept before deletion.</p><h2 id="what-next" tabindex="-1">What next? <a class="header-anchor" href="#what-next" aria-label="Permalink to &quot;What next?&quot;">​</a></h2><p>Once your assistants are connected, you talk to your memory through them: see <a href="/Kessho/en/agent/">With an agent</a>.</p>',21))])}const y=s(l,[["render",d]]);export{f as __pageData,y as default};
